INSERT INTO tasks VALUES('t-inspect-specs','p-7lhy',NULL,0,'Inspect UI specs and repo shape','Read ADR-0011, docs/18-ui-standardization.md, docs/brand/visual-language.md sections 4-7, root Cargo.toml, and any existing package manifests under packages/chief-ui-ts or crates/chief-ui if present. Produce concrete implementation constraints: token values, package tooling, export shape, and verification commands. Acceptance: enough context gathered to implement without touching forbidden paths.','done','generic',0,'default','2026-04-21 23:47:15','2026-04-21 23:47:15','2026-04-21 23:48:21','"Inspected ADR-0011, docs/18-ui-standardization.md, visual language sections 4-7, root Cargo.toml, package/crate layout, and available tooling. Implementation will create new packages/chief-ui-ts and crates/chief-ui, plus add the Rust crate to root Cargo.toml only. Verification will use npm scripts backed by global tsc/node:test and cargo package checks."',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-21 23:47:15',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-21 23:46:48','2026-04-21 23:48:21');
INSERT INTO tasks VALUES('t-ts-package','p-7lhy',NULL,0,'Implement TypeScript package','Create or update packages/chief-ui-ts only. Add tokens.css, React primitive components matching the exact catalog, public index exports only Chief primitives, Tauri vibrancy helper, internal shadcn scaffold with MIT attribution, font bundling assets/attribution, README 30-line example, and focused unit/snapshot/type-guard tests. Acceptance: package build and tests pass locally, public entry does not export Radix/Shadcn internals.','done','generic',0,'default','2026-04-21 23:48:21','2026-04-21 23:48:21','2026-04-21 23:57:17','"Implemented TS primitive kit and verified with npm run typecheck and npm test. Known environment gap: Inter Tight font binary could not be bundled because it is not present locally and network DNS resolution for github.com is blocked; CSS and attribution are wired for assets/fonts/InterTight-Regular.ttf."',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-21 23:48:21',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-21 23:46:53','2026-04-21 23:57:17');
INSERT INTO tasks VALUES('t-rust-crate','p-7lhy',NULL,0,'Implement Rust companion','Create or update crates/chief-ui only. Mirror Chief UI prop types and token constants in Rust, including closed enums for source colors and badges, motion/token data, and serde-friendly structs where appropriate. Acceptance: crate builds and tests pass without modifying other Rust crates.','done','generic',0,'default','2026-04-21 23:57:17','2026-04-21 23:57:17','2026-04-21 23:59:32','"Implemented crates/chief-ui with token constants, motion presets, closed source/badge enums, serde prop mirrors, and contract tests. Ran rustfmt directly. Cargo test is deferred until the verify task updates root Cargo.toml workspace membership."',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-21 23:57:17',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-21 23:46:59','2026-04-21 23:59:32');
INSERT INTO tasks VALUES('t-verify','p-7lhy',NULL,0,'Register workspace and verify','Update root Cargo.toml to include crates/chief-ui, then run npm/package checks for packages/chief-ui-ts and cargo checks/tests for crates/chief-ui or the workspace member. Acceptance: all requested builds/tests pass or any environment blocker is recorded with exact command output.','done','generic',0,'default','2026-04-21 23:59:32','2026-04-21 23:59:32','2026-04-22 00:01:43','"Registered crates/chief-ui in root Cargo.toml. Verified TS with npm run build, npm run typecheck, npm test. Verified Rust with cargo fmt --check -p chief-ui, cargo test -p chief-ui --offline, and cargo check -p chief-ui --offline. Non-offline cargo failed because DNS for index.crates.io is blocked. Public TS root entry exports only requested primitives. Inter Tight font asset remains unavailable in this sandbox; Inter and JetBrains Mono are bundled."',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-21 23:59:32',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-21 23:47:05','2026-04-22 00:01:43');
